var toggle = new ArcSwitch { Label = "自动保存", Checked = true };

toggle.CheckedChanged += async (_, _) =>
{
    if (!await SaveAsync(toggle.Checked))
    {
        toggle.Checked = !toggle.Checked;
    }
};

